/**
 * Provides shared Vite server setup for both dev shell launchers. It generates a
 * Vite config for each block.
 */
import { existsSync, mkdirSync, writeFileSync } from "node:fs";
import { relative, resolve } from "node:path";
import { RUNTIME_ERROR_CLIENT_SOURCE } from "./runtime-error-client.js";
/** Import specifier from `fromDir` to `toPath`, POSIX-style for ESM. */
function relativeImport(fromDir, toPath) {
    const rel = relative(fromDir, toPath).split(/[\\/]/).join("/");
    return rel.startsWith(".") ? rel : `./${rel}`;
}
/**
 * Write a per-block Vite config wrapper into the run's `.dev-shell/` directory.
 * Preserve the block's config and plugins, but pin its root and isolate its cache
 * from other blocks and concurrent runs. The wrapper also
 * serves `/manifest` from the block's slice of the worker manifest. The wrapper
 * plays the part production infra does and answers the SDK's manifest fetch
 * directly from the worker declaration. Return the wrapper path for Vite.
 */
export function writeBlockViteConfig(blockDir, capability, configDir, hostname) {
    const key = capability.key;
    const dir = configDir;
    mkdirSync(dir, { recursive: true });
    const blockConfig = ["ts", "mts", "cts", "js", "mjs", "cjs"]
        .map(ext => resolve(blockDir, `vite.config.${ext}`))
        .find(existsSync);
    const toRoot = relativeImport(dir, blockDir);
    const toCache = relativeImport(dir, resolve(dir, "cache", hostname));
    const baseImport = blockConfig !== undefined
        ? `import base from ${JSON.stringify(relativeImport(dir, blockConfig))}`
        : `const base = {}`;
    const file = resolve(dir, `${hostname}.mjs`);
    writeFileSync(file, `import { fileURLToPath } from "node:url"
${baseImport}

const here = p => fileURLToPath(new URL(p, import.meta.url))
const resolved =
	typeof base === "function"
		? await base({ command: "serve", mode: "development" })
		: await base

const manifest = ${JSON.stringify(JSON.stringify(capability.config.manifest))}

// Inject before the block entry module so errors thrown during module
// evaluation are reported even when the block never sends connect.
const captureRuntimeErrors = {
	name: "dev-shell:capture-runtime-errors",
	transformIndexHtml: {
		order: "pre",
		handler() {
			return [{
				tag: "script",
				attrs: { type: "module" },
				children: ${JSON.stringify(RUNTIME_ERROR_CLIENT_SOURCE)},
				injectTo: "head-pre",
			}]
		},
	},
}

const serveWorkerManifest = {
	name: "dev-shell:worker-block-manifest",
	enforce: "pre",
	configureServer(server) {
		server.middlewares.use((req, res, next) => {
			if (req.url?.split("?", 1)[0] !== "/manifest") {
				next()
				return
			}
			res.setHeader("Content-Type", "application/json")
			res.end(manifest)
		})
	},
}

export default {
	...resolved,
	root: here(${JSON.stringify(toRoot)}),
	cacheDir: here(${JSON.stringify(toCache)}),
	server: {
		...(resolved.server ?? {}),
		// Block servers are local development dependencies of the shell.
		host: "127.0.0.1",
	},
	define: {
		...(resolved.define ?? {}),
		// Initialization handshake scenarios fixture uses this key to identify the
		// selected scenario, via the custom block capability key. The key needs to be
		// serialized as a JavaScript string literal, then serialized again for this
		// generated config.
		"import.meta.env.VITE_CUSTOM_BLOCK_KEY": ${JSON.stringify(JSON.stringify(key))},
	},
	plugins: [
		serveWorkerManifest,
		captureRuntimeErrors,
		...(resolved.plugins ?? []),
	],
}
`);
    return file;
}
